+              >
+                <div className="select-cell" role="gridcell">
+                  <span className={`checkbox ${isSelected ? 'checked' : ''}`}>{isSelected && <CheckIcon />}</span>
+                </div>
+                {orderedColumns.map((column, columnIndex) => {
